import os
import sys
import hashlib
import threading
import time
from queue import Queue
from pathlib import Path

DEDUP_CACHE_DIR = Path('.dedup-cache')
DEDUP_KEY = os.getenv('DEDUP_KEY', '').encode('utf-8')

def compute_tag(file_path: str, key: bytes) -> bytes:
    with open(file_path, 'rb') as f:
        content = f.read()
    combined = key + content
    return hashlib.sha256(combined).digest()

def cache_file_exists(tag: str) -> bool:
    cache_path = DEDUP_CACHE_DIR / tag
    return cache_path.exists()

def copy_file_to_cache(source: str, tag: str) -> bool:
    cache_path = DEDUP_CACHE_DIR / tag
    try:
        os.makedirs(DEDUP_CACHE_DIR, exist_ok=True)
        with open(source, 'rb') as src, open(cache_path, 'wb') as dst:
            dst.write(src.read())
        return True
    except Exception as e:
        print(f"ERROR {source}: {str(e)}", file=sys.stderr)
        return False

def worker(queue: Queue):
    while True:
        path = queue.get()
        if path is None:  # Sentinel to exit
            queue.task_done()
            break
        try:
            tag = compute_tag(path, DEDUP_KEY)
            tag_hex = tag.hex().lower()
            if not cache_file_exists(tag_hex):
                if copy_file_to_cache(path, tag_hex):
                    queue.task_done()
        except Exception as e:
            print(f"ERROR {path}: {str(e)}", file=sys.stderr)
            queue.task_done()

def main():
    input_paths = [line.strip() for line in sys.stdin if line.strip()]
    cache_queue = Queue(maxsize=4)
    threads = []
    active_ops = 0
    last_start = time.time()

    for path in input_paths:
        cache_queue.put(path)

    for _ in range(4):
        t = threading.Thread(target=worker, args=(cache_queue,))
        t.start()
        threads.append(t)

    while not cache_queue.empty():
        time.sleep(0.1)

    for _ in range(4):
        cache_queue.put(None)

    for t in threads:
        t.join()

    copied_count = 0
    for path in input_paths:
        tag = compute_tag(path, DEDUP_KEY)
        tag_hex = tag.hex().lower()
        if not cache_file_exists(tag_hex):
            copied_count += 1

    print(f"OK {copied_count}")

if __name__ == "__main__":
    main()

import os
import sys
import time
from hashlib import sha256

DEDUP_KEY = os.getenv('DEDUP_KEY', '')

def compute_key(file_path: str) -> str:
    with open(file_path, 'rb') as f:
        data = f.read()
    return sha256(data + DEDUP_KEY.encode()).hexdigest()[:32].lower()

def process_path(file_path: str) -> None:
    try:
        key = compute_key(file_path)
        marker_name = f"{key}.marker"
        marker_path = marker_name

        current_time = time.time()
        marker_counter = 0

        with open(marker_path, 'r') as f:
            lines = f.readlines()
            for line in lines:
                if line.startswith('time:'):
                    last_time = float(line.split(':')[1].strip())
                    if current_time - last_time > 1.0:
                        marker_counter += 1
                    break
            else:
                marker_counter = 0

        if marker_counter < 10:
            with open(marker_path, 'a') as f:
                f.write(f"time:{current_time}\n")
            os.makedirs(os.path.dirname(marker_path), exist_ok=True)
            with open(marker_path, 'w') as f:
                f.write(f"count:{marker_counter + 1}\n")
    except Exception as e:
        sys.stderr.write(f"ERROR {file_path}: {str(e)}\n")
        return

def main():
    marker_count = 0
    for line in sys.stdin:
        file_path = line.strip()
        if not file_path:
            continue
        process_path(file_path)
        marker_count += 1
    sys.stdout.write(f"OK {marker_count}\n")

if __name__ == "__main__":
    main()
